const returnItems = [];

for (const item of $input.all()) {
  const body = item.json.body || {};
  const data = body.data || {};

  if (body.event !== "messages.upsert") continue;

  // 🚨 CORREÇÃO DEFINITIVA: ANTI-DUPLICAÇÃO HUMANA
  // A Evolution pode mandar a mensagem já com status "SERVER_ACK".
  // Por isso, vamos bloquear APENAS os status de confirmação (Entrega, Leitura ou Play).
  // Assim, a sua mensagem digitada (SERVER_ACK ou PENDING) passa perfeitamente!
  if (data.key?.fromMe === true && data.status) {
      if (["DELIVERY_ACK", "READ", "PLAYED"].includes(data.status)) {
          continue; 
      }
  }

  if (!data.message) continue;

  let remoteJid = data.key?.remoteJid || "";
  let phoneNumber = remoteJid.split('@')[0]; 

  if (remoteJid.includes('@lid')) {
    remoteJid = `${phoneNumber}@s.whatsapp.net`;
  }

  // 🚨 BARREIRA DE RESTRIÇÃO DE NÚMEROS 🚨
  const numerosBloqueados = [
      "554191194738", "5541991194738", // Primeiro número
      "554195718577", "5541995718577"  // Segundo número
  ];

  if (numerosBloqueados.includes(phoneNumber)) {
      continue;
  }
  // --------------------------------------

  const msg = data.message?.ephemeralMessage?.message || data.message;

  let messageText = "";
  let isAudio = false;
  let isImage = false;
  let imageBase64 = "";

  // CAÇADOR DE TEXTOS, ÁUDIOS E IMAGENS
  if (msg?.conversation) {
    messageText = msg.conversation;
  } else if (msg?.extendedTextMessage?.text) {
    messageText = msg.extendedTextMessage.text;
  } else if (msg?.audioMessage) {
    isAudio = true;
  } else if (msg?.reactionMessage?.text) {
    // 🚨 BLOQUEIO DE REAÇÕES: Mata o fluxo aqui para economizar tokens
    continue; 
  } else if (msg?.imageMessage) {
    isImage = true;
    messageText = msg.imageMessage.caption || ""; 
    imageBase64 = data.message.base64 || data.base64 || ""; 
  } else if (msg?.documentMessage) {
      messageText = `[O paciente enviou um arquivo PDF/Documento chamado: ${msg.documentMessage.title}]`;
  }

  // Se não tem texto, nem áudio, nem imagem, aborta
  if (!messageText && !isAudio && !isImage) continue; 

  const fromMe = data.key?.fromMe === true;
  const isSilvia = messageText.includes('\u200D'); 

  let tipoRota = "paciente";

  if (fromMe) {
      if (isSilvia) {
          // É a Silvia respondendo ou um Disparo automático. IGNORA.
          continue;
      } else if (messageText === '/retomar') {
          // Humano mandou o comando de religar o bot
          tipoRota = "retomar"; 
      } else {
          // Humano digitou uma mensagem real (ex: "silvia, cade vc?"). Rota para PAUSAR o bot!
          tipoRota = "pausar"; 
      }
  }

  returnItems.push({
    json: {
      sessionId: phoneNumber,             
      remoteJid: remoteJid,               
      senderNumber: phoneNumber,         
      pushName: data.pushName || "Paciente",                 
      text: messageText,                  
      isAudio: isAudio,
      isImage: isImage, 
      imageBase64: imageBase64, 
      evoKey: data.key,
      evoMessage: data.message,
      fromMe: fromMe,
      tipoRota: tipoRota 
    }
  });
}

return returnItems;

