// Pega o texto gerado pela Silvia
const textoOriginal = $input.first().json.output || "";

// 🚨 FILTRO ANTI-VAZAMENTO LANGCHAIN, TOOLS E TAGS DE SISTEMA 🚨
// 1. Remove chamadas de ferramentas vazadas (ex: "Calling Tool_X with input: {...}")
// 2. Remove END_OF_TURN, [TICKET_CLOSE] e outras sujeiras do LangChain
let textoTratado = textoOriginal
    .replace(/Calling Tool_[\w]+ with input:.*?(?:\n|$)/g, '')
    .replace(/END_OF_TURN/g, '')
    .replace(/\[TICKET_CLOSE\]/g, '')
    .trim();

// Se, após limpar a "sujeira", não sobrar texto nenhum,
// retornamos array vazio para não mandar nada no WhatsApp.
if (textoTratado === "") {
    return [];
}

// Divide o texto onde houver o caractere "|"
const blocos = textoTratado.split('|');

const mensagensQuebradas = [];

// Limpa espaços vazios e cria um item novo para cada balão
for (let bloco of blocos) {
  let textoLimpo = bloco.trim();
  if (textoLimpo.length > 0) {
    mensagensQuebradas.push({
      json: {
        text: textoLimpo
      }
    });
  }
}

// Retorna a LISTA de itens para o n8n processar no Loop
return mensagensQuebradas;

// O resultado da query Lua
const filaTextos = $json.result || $json; 

// Se o Redis não retornou um Array válido de textos (o banco estava vazio), 
// nós simplesmente MORREMOS a execução aqui voltando array vazio [].
if (!Array.isArray(filaTextos) || filaTextos.length === 0) {
    return [];
}

// O cofre estava cheio! Vamos unir os textos
const textoCompleto = filaTextos.join(" | ");

// Clonamos os atributos originais lá do começo do fluxo do paciente
const originalData = $('Filtro_Eventos_Webhook').first().json;
return [{
  json: {
    ...originalData,
    text: textoCompleto
  }
}];

